INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Anweisungsfolge immer linear?', 2, '[{"text": "Nein", "correct": true, "because": "Verzweigungen möglich"}, {"text": "Ja", "correct": false, "because": "Nicht nur sequenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Anweisungsfolge?', 3, '[{"text": "Aufgabe schrittweise lösen", "correct": true, "because": "Definiert Ablauf"}, {"text": "Code verschlüsseln", "correct": false, "because": "Kein Fokus"}, {"text": "Speicher sparen", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Anweisungsfolge?', 5, '[{"text": "Befehle", "correct": true, "because": "Grundbausteine"}, {"text": "Kontrollstrukturen", "correct": true, "because": "Steuern Ablauf"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Anweisungsfolge kann Schleifen enthalten. b) Sie ist immer unabhängig von Eingaben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eingaben beeinflussen Ablauf"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung einer Anweisungsfolge?', 4, '[{"text": "Reihenfolge", "correct": false, "because": "Entscheidend für Logik"}, {"text": "Bedingungen", "correct": false, "because": "Steuern Ablauf"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Anweisungsfolge Bedingungen enthalten kann?', 2, '[{"text": "Ja", "correct": true, "because": "Verzweigungen üblich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für eine wiederholte Anweisungsfolge?', 3, '[{"text": "Schleife", "correct": true, "because": "Wiederholt Befehle"}, {"text": "Funktion", "correct": false, "because": "Kapselt, wiederholt nicht"}, {"text": "Bedingung", "correct": false, "because": "Verzweigt nur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einer komplexen Anweisungsfolge?', 5, '[{"text": "Verzweigungen", "correct": true, "because": "Bedingte Abläufe"}, {"text": "Schleifen", "correct": true, "because": "Wiederholungen"}, {"text": "Kommentare", "correct": false, "because": "Dokumentation, kein Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Anweisungsfolgen sind deterministisch. b) Sie sind immer kurz. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Länge variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Anweisungsfolge unwichtig?', 4, '[{"text": "Logische Reihenfolge", "correct": false, "because": "Entscheidend für Ergebnis"}, {"text": "Kontrollelemente", "correct": false, "because": "Steuern Ablauf"}, {"text": "Codeformatierung", "correct": true, "because": "Ästhetik, kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss eine Anweisungsfolge eindeutig sein?', 2, '[{"text": "Ja", "correct": true, "because": "Klarheit für Ausführung"}, {"text": "Nein", "correct": false, "because": "Unklarheit unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine klare Anweisungsfolge?', 4, '[{"text": "Vorhersehbares Ergebnis", "correct": true, "because": "Logik garantiert"}, {"text": "Einfache Wartung", "correct": true, "because": "Leicht verständlich"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Anweisungsfolgen nur linear ablaufen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schleifen und Bedingungen möglich"}, {"text": "Ja", "correct": false, "because": "Nicht nur linear"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Anweisungsfolge?', 3, '[{"text": "Korrektheit", "correct": true, "because": "Sichert Ergebnis"}, {"text": "Schnelligkeit", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anweisungsfolgen können rekursiv sein. b) Sie sind immer sprachabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abstrakt definierbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine unklare Anweisungsfolge?', 5, '[{"text": "Fehlerhafte Ergebnisse", "correct": true, "because": "Logik unklar"}, {"text": "Schwere Wartung", "correct": true, "because": "Schwer verständlich"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist in einer Anweisungsfolge unwichtig?', 3, '[{"text": "Ablaufsteuerung", "correct": false, "because": "Definiert Logik"}, {"text": "Befehlsreihenfolge", "correct": false, "because": "Entscheidend"}, {"text": "Autorname", "correct": true, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Anweisungsfolge parallel ablaufen?', 3, '[{"text": "Ja", "correct": true, "because": "Mit Threads möglich"}, {"text": "Nein", "correct": false, "because": "Nicht nur sequenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Anweisungsfolge Unterbrechungen erlaubt?', 2, '[{"text": "Ja", "correct": true, "because": "Interrupts möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für eine bedingte Anweisungsfolge?', 4, '[{"text": "If-Else", "correct": true, "because": "Verzweigt Ablauf"}, {"text": "Schleife", "correct": false, "because": "Wiederholt nur"}, {"text": "Funktion", "correct": false, "because": "Kapselt, nicht bedingt"}]');
